<?php
declare(strict_types=1);
header('X-Content-Type-Options: nosniff');header('Cache-Control: no-store');
$db=pg_connect('dbname=bf4_battle_reports user=www-data');if(!$db){http_response_code(503);exit('DB unavailable');}
function rows($db,$q){$r=pg_query($db,$q);if(!$r)throw new RuntimeException();return pg_fetch_all($r)?:[];}
if(isset($_GET['json'])){header('Content-Type: application/json');try{
pg_query($db,"SET statement_timeout='3000ms'");
$snapshot=@json_decode((string)@file_get_contents('/var/cache/bf4br-node-versions.json'),true);
$journals=@json_decode((string)@file_get_contents('/var/cache/bf4br-journal-errors.json'),true);
echo json_encode(['time'=>gmdate('c'),
'versions'=>$snapshot?:['updated_at'=>null,'versions'=>[]],
'journals'=>$journals?:['updated_at'=>null,'entries'=>[]],
'nodes'=>rows($db,"SELECT c.node_name,c.paused,c.persona_workers,coalesce(h.running_persona,0) running_persona,coalesce(h.running_report,0) running_report,h.seen_at,a.role,a.platform FROM bf4br_node_controls c LEFT JOIN bf4br_node_heartbeats h USING(node_name) LEFT JOIN bf4br_worker_assignments a USING(node_name) WHERE c.node_name <> 'rnt-reports' ORDER BY c.node_name"),
'errors'=>rows($db,"SELECT attempted_at,platform,battlelog_report_id,NULL::text AS node_name,CASE WHEN http_status IS NOT NULL AND http_status>=400 THEN 'HTTP '||http_status WHEN curl_exit IS NOT NULL AND curl_exit<>0 THEN 'curl '||curl_exit ELSE outcome END AS error_type, left(coalesce(error_message,outcome),240) AS message FROM battle_report_fetch_log WHERE (http_status>=400 OR curl_exit<>0 OR outcome IN ('error','failed')) ORDER BY id DESC LIMIT 40"),
'history_errors'=>rows($db,"SELECT occurred_at AS attempted_at,platform,item_id,node_name,CASE job_kind WHEN 'historical_persona' THEN 'Historical persona' WHEN 'daily_persona' THEN 'Daily persona' WHEN 'report' THEN 'Report' ELSE 'Daily report' END AS error_type,left(error_message,240) AS message FROM bf4br_collector_error_history WHERE occurred_at>now()-interval '24 hours' ORDER BY occurred_at DESC LIMIT 60"),
'internal_errors'=>rows($db,"SELECT updated_at AS attempted_at,platform,persona_id AS item_id,split_part(lease_owner,'-',1)||'-'||split_part(lease_owner,'-',2) AS node_name,'Historical persona' AS error_type,left(last_error,240) AS message FROM bf4br_persona_jobs WHERE last_error IS NOT NULL AND updated_at>now()-interval '24 hours' UNION ALL SELECT updated_at,platform,persona_id,split_part(lease_owner,'-',1)||'-'||split_part(lease_owner,'-',2),'Daily persona',left(last_error,240) FROM bf4br_daily_persona_jobs WHERE last_error IS NOT NULL AND updated_at>now()-interval '24 hours' ORDER BY attempted_at DESC LIMIT 40"),
'recent_429_nodes'=>rows($db,"SELECT DISTINCT split_part(lease_owner,'-',1)||'-'||split_part(lease_owner,'-',2) AS node_name FROM (SELECT lease_owner FROM bf4br_persona_jobs WHERE updated_at>now()-interval '10 minutes' AND last_error ILIKE '%429%' UNION ALL SELECT lease_owner FROM bf4br_daily_persona_jobs WHERE updated_at>now()-interval '10 minutes' AND last_error ILIKE '%429%') e WHERE lease_owner IS NOT NULL AND lease_owner<>''"),
'personas'=>rows($db,"SELECT j.platform,j.persona_id,coalesce(p.current_name,'Unknown') name,j.lease_owner,j.updated_at FROM bf4br_persona_jobs j LEFT JOIN players p ON p.platform=j.platform AND p.persona_id=j.persona_id WHERE j.state='leased' AND j.lease_until>now() ORDER BY j.platform,j.lease_owner LIMIT 100"),
'jobs'=>rows($db,"SELECT platform,battlelog_report_id,lease_owner,updated_at FROM bf4br_report_jobs WHERE state='leased' AND lease_until>now() ORDER BY platform,lease_owner LIMIT 100"),
'new'=>rows($db,"SELECT r.platform,r.battlelog_report_id,r.imported_at,d.report_timestamp AS match_timestamp FROM battle_report_raw r LEFT JOIN history_discoveries d ON d.platform=r.platform AND d.battlelog_report_id=r.battlelog_report_id WHERE r.imported_at IS NOT NULL ORDER BY r.imported_at DESC LIMIT 60"),
'counts'=>rows($db,"SELECT platform,count(*) n FROM battle_report_raw WHERE imported_at>now()-interval '10 minutes' GROUP BY platform")],JSON_INVALID_UTF8_SUBSTITUTE);
}catch(Throwable $e){http_response_code(503);echo '{"error":"Monitoring unavailable"}';}exit;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Collection | BF4 Battle Reports</title><style>
*{box-sizing:border-box}body{background:#0c121b;color:#e6edf7;font:14px/1.5 system-ui;margin:0}.wrap{width:100%;max-width:none;margin:0;padding:24px 0}a{color:#8ec8ff;text-decoration:none}a:hover{text-decoration:underline}header{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;border-bottom:1px solid #35465b;padding-bottom:20px}nav{display:flex;gap:18px;flex-wrap:wrap}.brand{font-size:23px;font-weight:800}.brand span{color:#f4a24c}h1{font-size:29px;margin-bottom:3px}.muted{color:#9db1c7}.cards{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin:20px 0}.card,.panel{background:#142233;border:1px solid #31445b;border-radius:12px;padding:16px}.card strong{display:block;font-size:28px}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.6fr);gap:16px}.panel{min-width:0;margin-bottom:16px}.processing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.processing-grid table{width:100%;min-width:0}.processing-grid td,.processing-grid th{padding:8px 6px;font-size:12px}.processing-grid td{overflow:hidden;text-overflow:ellipsis}.processing-grid .scroll{overflow-x:auto}@media(min-width:1100px){.processing-grid .scroll{overflow-x:hidden}}h2{font-size:18px;margin:0 0 12px}.scroll{max-height:520px;overflow:auto;scrollbar-gutter:stable}#errors-table{width:100%}table{border-collapse:collapse;width:100%;text-align:left}th{position:sticky;top:0;background:#20354b;color:#adc0d3}td,th{padding:9px;border-bottom:1px solid #304156;white-space:nowrap}td.name{white-space:nowrap;overflow-wrap:normal}#errors-table{table-layout:fixed;width:100%;min-width:0}#errors-table th:nth-child(1){width:24%}#errors-table th:nth-child(2){width:9%}#errors-table th:nth-child(3){width:13%}#errors-table th:nth-child(4){width:17%}#errors-table th:nth-child(5){width:19%}#errors-table td,#errors-table th{padding:8px 6px;overflow:hidden;text-overflow:ellipsis}#errors-table td:last-child{overflow:hidden;text-overflow:ellipsis}.pc{color:#f6b56d}.ps{color:#82baff}.xb{color:#80e6a3}button{background:#233b55;border:1px solid #58718c;color:white;border-radius:6px;padding:8px 12px;cursor:pointer}@media(max-width:1050px){.cards{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:850px){.grid,.processing-grid{grid-template-columns:1fr}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:450px){.cards{grid-template-columns:1fr}} 
</style><link rel="stylesheet" href="bf4br-layout.css?v=1"></head><body><?php require_once __DIR__ . "/bf4br-layout.php"; bf4br_header("live"); ?><div class="wrap"><h1>Live collection monitor</h1><p class="muted">Current worker leases and incoming battle reports · automatically refreshes every 5 seconds</p><button id="toggle">Pause updates</button> <span id="status" class="muted">Connecting…</span>
<div class="cards"><div class="card">Active persona jobs<strong id="pc">—</strong></div><div class="card">Active report jobs<strong id="rc">—</strong></div><div class="card">Imported in 10 minutes<strong id="ic">—</strong></div><div class="card">Latest import<strong id="age">—</strong></div><div class="card" title="Nodes with a recorded HTTP 429 in the last 10 minutes or currently reporting a 429 cooldown. Errors with no recorded node cannot be attributed.">429 Hell<strong id="hell">— Nodes</strong></div></div>
<div class="grid"><section class="panel"><h2>Fleet nodes and versions</h2><p class="muted" id="version-age">Versions checked every minute</p><div class="scroll"><table><thead><tr><th>Node</th><th>Version</th><th>Status</th><th>Role</th><th>Persona / report</th></tr></thead><tbody id="nodes"></tbody></table></div></section><section class="panel"><h2>Recent HTTP / internal errors</h2><p class="muted">Report fetch failures and persona job errors (last 24h for internal errors)</p><div class="scroll"><table id="errors-table"><thead><tr><th>Browser time</th><th>Node</th><th>Platform</th><th>Error</th><th>Report / Persona</th><th>Details</th></tr></thead><tbody id="errors"></tbody></table></div></section></div>
<section class="panel"><h2>Worker systemd warnings and exceptions</h2><p class="muted" id="journal-age">Checking journal snapshots</p><div class="scroll"><table><thead><tr><th>Node</th><th>Journal entry (last 10 minutes)</th></tr></thead><tbody id="journals"></tbody></table></div></section>
<div class="grid processing-grid"><section class="panel"><h2>Personas currently being processed</h2><div class="scroll"><table><thead><tr><th>Platform</th><th>Player name</th><th>Persona ID</th><th>Worker</th><th>Claimed (local)</th></tr></thead><tbody id="personas"></tbody></table></div></section><section class="panel"><h2>Reports currently being processed</h2><div class="scroll"><table><thead><tr><th>Platform</th><th>Report ID</th><th>Worker</th><th>Claimed (local)</th></tr></thead><tbody id="jobs"></tbody></table></div></section></div>
<section class="panel"><h2>Incoming battle reports · latest 60</h2><div class="scroll"><table><thead><tr><th>Imported (local)</th><th>Match played (local)</th><th>Platform</th><th>Report ID</th><th>Scoreboard</th></tr></thead><tbody id="new"></tbody></table></div></section><p class="muted">A lease means a worker claimed the job, not necessarily that a network request is underway. Match dates come from locally recorded Battlelog discovery timestamps; missing timestamps display a dash. Names reflect the latest locally recorded player name. Read-only public monitor.</p></div><?php bf4br_footer(); ?><script>
const el=id=>document.getElementById(id),names={1:'PC',32:'PlayStation',64:'Xbox'},cls={1:'pc',32:'ps',64:'xb'};let paused=false,busy=false,last=null;
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plat=v=>'<span class="'+(cls[v]||'')+'">'+safe(names[v]||v)+'</span>';
const parseTime=v=>{if(!v)return NaN;const normalized=String(v).replace(' ','T').replace(/\.(\d{3})\d+/,'.$1').replace(/([+-]\d{2})$/,'$1:00');return Date.parse(normalized);};
const date=v=>{if(!v)return '—';const t=new Date(parseTime(v));return Number.isNaN(t.getTime())?'—':t.toLocaleString(undefined,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true,timeZoneName:'short'});};
const age=v=>{if(!v)return '—';let s=Math.max(0,Math.floor((Date.now()-parseTime(v))/1000));return s<60?s+'s ago':Math.floor(s/60)+'m ago';};
function fill(id,data,fn,cols){el(id).innerHTML=data.length?data.map(fn).join(''):'<tr><td colspan="'+cols+'" class="muted">No active jobs</td></tr>';}
function render(d){
el('version-age').textContent='Versions checked '+age(d.versions?.updated_at)+' · refresh every minute';
el('journal-age').textContent='Journal checked '+age(d.journals?.updated_at);
fill('journals',d.journals?.entries||[],r=>'<tr><td>'+safe(r.node)+'</td><td class="name">'+safe(r.message)+'</td></tr>',2);
fill('nodes',d.nodes||[],r=>'<tr><td>'+safe(r.node_name)+'</td><td>'+safe(d.versions?.versions?.[r.node_name]||'unknown')+'</td><td>'+safe(r.paused==='t'?'Paused':!r.seen_at||Date.now()-parseTime(r.seen_at)>60000?'Offline':(d.versions?.cooldowns?.[r.node_name]?.until_epoch*1000>Date.now()?'Rate limited — cooldown until '+date(new Date(d.versions.cooldowns[r.node_name].until_epoch*1000)):'Online'))+'</td><td>'+safe(r.role||'—')+' '+(r.platform?plat(r.platform):'')+'</td><td>'+safe(r.running_persona)+' / '+safe(r.running_report)+'</td></tr>',5);
fill('errors',[...(d.errors||[]),...(d.internal_errors||[]).filter(x=>!(d.history_errors||[]).some(y=>y.platform===x.platform&&y.item_id===x.item_id&&y.error_type===x.error_type&&Math.abs(parseTime(y.attempted_at)-parseTime(x.attempted_at))<60000)),...(d.history_errors||[])].sort((a,b)=>parseTime(b.attempted_at)-parseTime(a.attempted_at)).slice(0,60),r=>'<tr><td>'+date(r.attempted_at)+'</td><td>'+safe(r.node_name||'Unknown')+'</td><td>'+plat(r.platform)+'</td><td>'+safe(r.error_type)+'</td><td>'+safe(r.battlelog_report_id||r.item_id)+'</td><td class="name">'+safe(r.message)+'</td></tr>',6);
const hellNodes=new Set((d.recent_429_nodes||[]).map(x=>x.node_name));for(const n of d.nodes||[]){if(Number(d.versions?.cooldowns?.[n.node_name]?.until_epoch||0)*1000>Date.now())hellNodes.add(n.node_name);}el('hell').textContent=hellNodes.size+' Nodes';
el('pc').textContent=d.personas.length;el('rc').textContent=d.jobs.length;el('ic').textContent=d.counts.reduce((a,x)=>a+Number(x.n),0);last=d.new[0]?.imported_at||null;el('age').textContent=age(last);
fill('personas',d.personas,r=>'<tr><td>'+plat(r.platform)+'</td><td class="name">'+safe(r.name)+'</td><td><a href="battle-reports.php?persona='+encodeURIComponent(r.persona_id)+'&platform='+encodeURIComponent(r.platform)+'">'+safe(r.persona_id)+'</a></td><td>'+safe(r.lease_owner)+'</td><td>'+date(r.updated_at)+'</td></tr>',5);
fill('jobs',d.jobs,r=>'<tr><td>'+plat(r.platform)+'</td><td>'+safe(r.battlelog_report_id)+'</td><td>'+safe(r.lease_owner)+'</td><td>'+date(r.updated_at)+'</td></tr>',4);
fill('new',d.new,r=>'<tr><td>'+date(r.imported_at)+'</td><td>'+date(r.match_timestamp)+'</td><td>'+plat(r.platform)+'</td><td>'+safe(r.battlelog_report_id)+'</td><td><a href="battle-reports.php?report='+encodeURIComponent(r.battlelog_report_id)+'&platform='+encodeURIComponent(r.platform)+'">View scoreboard →</a></td></tr>',4);
el('status').textContent='Live · updated '+new Date().toLocaleTimeString();}
async function refresh(){if(paused||busy||document.hidden)return;busy=true;let ctl=new AbortController(),timeout=setTimeout(()=>ctl.abort(),4500);try{let r=await fetch('battle-reports-live.php?json=1',{cache:'no-store',signal:ctl.signal});if(!r.ok)throw Error('HTTP '+r.status);render(await r.json());}catch(e){el('status').textContent='Connection issue: '+e.message;}finally{clearTimeout(timeout);busy=false;}}
el('toggle').onclick=()=>{paused=!paused;el('toggle').textContent=paused?'Resume updates':'Pause updates';if(paused)el('status').textContent='Paused';else refresh();};setInterval(refresh,5000);setInterval(()=>{if(last)el('age').textContent=age(last);},1000);refresh();
</script></body></html>
